package com.dramastudio.template;
import com.dramastudio.entity.*; import com.dramastudio.repository.*; import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class BuiltinTemplateInitializer implements ApplicationRunner {
 private final TemplateRepository templates; private final TemplateVersionRepository versions; private final ObjectMapper json;
 public BuiltinTemplateInitializer(TemplateRepository t,TemplateVersionRepository v,ObjectMapper j){templates=t;versions=v;json=j;}
 @Override @Transactional public void run(ApplicationArguments args)throws Exception{for(var d:NodeCatalog.all().values())if(templates.findByNodeTypeAndScope(d.type(),"BUILT_IN").isEmpty()){Template t=new Template();t.nodeType=d.type();t.name=d.label();t.scope="BUILT_IN";t.status="ACTIVE";templates.save(t);var sections=new ArrayList<Map<String,Object>>();d.params().forEach((k,p)->sections.add(section(k,p)));var def=new LinkedHashMap<String,Object>();def.put("schemaVersion","1.0");def.put("nodeType",d.type());def.put("name",t.name);def.put("version","1.0.0");def.put("scope","BUILT_IN");def.put("status","PUBLISHED");def.put("sections",sections);def.put("negativePrompt",Map.of("defaultValue",defaultNegative(d.type()),"editable",true));def.put("modelParams",Map.of());def.put("outputSchema",Map.of("$ref","schema://"+d.type().toLowerCase(Locale.ROOT)+"/v1"));String definition=json.writeValueAsString(def);TemplateVersion v=new TemplateVersion();v.id=UUID.randomUUID().toString();v.templateId=t.id;v.version="1.0.0";v.status="PUBLISHED";v.schemaVersion="1.0";v.definitionJson=definition;v.checksum=sha(definition);v.changeLog="内置鲸剧模板初始版本";v.createdAt=Instant.now().toString();v.publishedAt=v.createdAt;versions.save(v);}}
 private Map<String,Object> section(String key,NodeCatalog.Param p){var m=new LinkedHashMap<String,Object>();m.put("key",key);m.put("label",key);m.put("valueType",p.type());m.put("source",p.source());m.put("defaultValue",p.defaultValue());m.put("editable",p.editable());m.put("required",false);m.put("order",0);return m;}
 private String defaultNegative(String type){return type.contains("IMAGE")||type.contains("VIDEO")?"low quality, artifacts, changed face, extra limbs, watermark":"";}
 private String sha(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}
}
